int main(){try{using namespace tao::dual;Config c;c.layers=1;c.d=3;c.s=2;c.m=2;c.e=4;c.vocab=261;CpuModel m(c);std::string id(64,'a'),path="build/bundle_v2_unit.dsb";save_bundle(m,path,id);if(load_bundle(path,id).w!=m.w)throw std::runtime_error("roundtrip");int count=0;auto reject=[&](auto fn){bool yes=false;try{fn();}catch(const std::exception&){yes=true;}if(!yes)throw std::runtime_error("accepted");++count;};reject([&]{load_bundle(path,std::string(64,'b'));});reject([&]{save_bundle(m,path,id);});std::ifstream f(path,std::ios::binary);std::string b((std::istreambuf_iterator<char>(f)),{});auto bad=[&](std::string x){std::ofstream o("build/bundle_bad.dsb",std::ios::binary);o.write(x.data(),x.size());o.close();reject([&]{load_bundle("build/bundle_bad.dsb",id);});};auto x=b;x.back()^=1;bad(x);bad(b.substr(0,b.size()-1));x=b;x[4]=char(255);bad(x);x=b;x.push_back('x');bad(x);printf("PASS roundtrip rejection_cases=%d\n",count);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
